// Validate the review outcome and build a hand-off task record.
// This node only creates a RECORD. It never changes an order, refund or delivery (P05).
const item = $input.first().json;
const body = item.body || item;
const required = ['ticket_id', 'draft_id', 'draft_version', 'route', 'destination', 'action', 'reviewer'];
const validActions = ['approved', 'edited_and_approved', 'rejected'];
const errors = [];
const missing = required.filter(k => body[k] === undefined || body[k] === null || body[k] === '');
if (missing.length) errors.push('missing fields: ' + missing.join(', '));
if (body.action && !validActions.includes(body.action)) errors.push('invalid action: ' + body.action);
if (errors.length) {
  return [{ json: { valid: false, status: 'rejected', errors } }];
}
if (body.action === 'rejected') {
  return [{ json: { valid: true, status: 'no_task', reason: 'Draft rejected by reviewer; no hand-off created',
                    ticket_id: body.ticket_id, draft_id: body.draft_id } }];
}
const priorities = {
  safety_queue: ['urgent', 1], service_lead: ['high', 8], logistics_followup: ['normal', 24],
  manager_decision: ['normal', 24], returns_review: ['normal', 24], service_review: ['normal', 48],
  agent_followup: ['normal', 24], agent_review: ['normal', 24]
};
const [priority, dueHours] = priorities[body.destination] || ['normal', 24];
return [{ json: {
  valid: true,
  status: 'task_created',
  run_id: 'WF-' + Date.now().toString(36).toUpperCase(),
  ticket_id: body.ticket_id,
  draft_id: body.draft_id,
  task: {
    queue: body.destination,
    priority,
    due_hours: dueHours,
    title: body.route + ' for ticket ' + body.ticket_id,
    policy_ids: body.policy_ids || [],
    approved_by: body.reviewer,
    draft_version: body.draft_version
  },
  note: 'Record only. No order, refund or delivery was changed.'
} }];
